#[test]
fn test_attributes_set_replace_and_repeat() {
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut a: i32 = 0;
    mt_tree(nodes, attrs, regions, text, pages, ledger, layout);
    mt_text(text, 20);
    crate::testport::assert_eq(node_attr(nodes, attrs, 2, fk_level()), -1, "no attribute yet");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 2, fk_level(), 77), 77, "default when absent");
    node_set_attr_int(nodes, attrs, 2, fk_level(), 4);
    node_set_attr_text(nodes, attrs, 2, fk_label(), 10, 6);
    node_set_attr_node(nodes, attrs, 2, fk_target(), 7);
    node_set_attr_bool(nodes, attrs, 2, fk_checked(), 5);
    crate::testport::assert_eq(attr_count(attrs), 4, "four attributes");
    crate::testport::assert_eq(node_attr_head(nodes, 2), 0, "head is the first");
    a = node_attr(nodes, attrs, 2, fk_label());
    crate::testport::assert_eq(a, 1, "label is attr 1");
    crate::testport::assert_eq(attr_key(attrs, a), fk_label(), "key");
    crate::testport::assert_eq(attr_vkind(attrs, a), av_text(), "a text value");
    crate::testport::assert_eq(attr_value(attrs, a), 10, "run start");
    crate::testport::assert_eq(attr_len(attrs, a), 6, "run length");
    crate::testport::assert_eq(attr_next(attrs, a), 2, "chain order is insertion order");
    a = node_attr(nodes, attrs, 2, fk_target());
    crate::testport::assert_eq(attr_vkind(attrs, a), av_node(), "a node value");
    crate::testport::assert_eq(attr_value(attrs, a), 7, "target node");
    a = node_attr(nodes, attrs, 2, fk_checked());
    crate::testport::assert_eq(attr_vkind(attrs, a), av_bool(), "a bool value");
    crate::testport::assert_eq(attr_value(attrs, a), 1, "non-zero is stored as 1");
    crate::testport::assert_eq(attr_next(attrs, a), -1, "the chain ends");
    node_set_attr_int(nodes, attrs, 2, fk_level(), 5);
    crate::testport::assert_eq(attr_count(attrs), 4, "set replaced in place");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 2, fk_level(), 77), 5, "the new value");
    node_set_attr_text(nodes, attrs, 2, fk_level(), 3, 2);
    crate::testport::assert_eq(attr_vkind(attrs, 0), av_text(), "set may change the value kind");
    crate::testport::assert_eq(attr_len(attrs, 0), 2, "and the length");
    node_set_attr_bool(nodes, attrs, 2, fk_checked(), 0);
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 2, fk_checked(), 9), 0, "false is 0");
    node_add_attr_int(nodes, attrs, 7, fk_pages(), 1);
    node_add_attr_int(nodes, attrs, 7, fk_pages(), 2);
    node_add_attr_int(nodes, attrs, 7, fk_pages(), 9);
    node_add_attr_text(nodes, attrs, 7, fk_labels(), 0, 1);
    crate::testport::assert_eq(attr_count(attrs), 8, "add always appends");
    a = node_attr(nodes, attrs, 7, fk_pages());
    crate::testport::assert_eq(attr_value(attrs, a), 1, "first of the repeated key");
    a = attr_find_next(attrs, a, fk_pages());
    crate::testport::assert_eq(attr_value(attrs, a), 2, "second");
    a = attr_find_next(attrs, a, fk_pages());
    crate::testport::assert_eq(attr_value(attrs, a), 9, "third");
    crate::testport::assert_eq(attr_find_next(attrs, a, fk_pages()), -1, "no fourth");
    crate::testport::assert_eq(node_attr(nodes, attrs, 7, fk_alt()), -1, "a key never set");
    crate::testport::assert_eq(node_attr(nodes, attrs, 3, fk_pages()), -1, "another node's chain is its own");
    crate::testport::assert_eq(model_check(nodes, attrs, regions, text, pages, ledger, layout, &mut crate::port::Cells::new()), 0, "well formed");
}
#[test]
fn test_text_arena_holds_scalar_values_only() {
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::testport::assert_eq(text_append_cp(text, 72), 0, "index written");
    crate::testport::assert_eq(text_append_cp(text, 233), 1, "index written");
    text_append_cp(text, 128512);
    text_append_cp(text, -1);
    text_append_cp(text, 55296);
    text_append_cp(text, 57343);
    text_append_cp(text, 1114111);
    text_append_cp(text, 1114112);
    text_append_cp(text, 0);
    crate::testport::assert_eq(text_len(text), 9, "nine cells");
    crate::testport::assert_eq(text_at(text, 0), 72, "H");
    crate::testport::assert_eq(text_at(text, 1), 233, "e acute");
    crate::testport::assert_eq(text_at(text, 2), 128512, "a code point past the BMP is one cell");
    crate::testport::assert_eq(text_at(text, 3), 65533, "negative becomes U+FFFD");
    crate::testport::assert_eq(text_at(text, 4), 65533, "a high surrogate becomes U+FFFD");
    crate::testport::assert_eq(text_at(text, 5), 65533, "a low surrogate becomes U+FFFD");
    crate::testport::assert_eq(text_at(text, 6), 1114111, "U+10FFFF is kept");
    crate::testport::assert_eq(text_at(text, 7), 65533, "past U+10FFFF becomes U+FFFD");
    crate::testport::assert_eq(text_at(text, 8), 0, "NUL is a scalar value");
}
#[test]
fn test_utf8_valid_and_invalid_sequences() {
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let n: i32 = text_append_utf8(text, &crate::testport::hex_blob("41c3a9e282acf09f988080c0e080eda080f4908080 41")[..], 0, 22);
    crate::testport::assert_eq(n, 16, "sixteen code points: four good, eleven replacements, one more");
    crate::testport::assert_eq(text_len(text), 16, "and sixteen cells");
    crate::testport::assert_eq(text_at(text, 0), 65, "ASCII");
    crate::testport::assert_eq(text_at(text, 1), 233, "two bytes");
    crate::testport::assert_eq(text_at(text, 2), 8364, "three bytes");
    crate::testport::assert_eq(text_at(text, 3), 128512, "four bytes");
    crate::testport::assert_eq(text_at(text, 4), 65533, "a stray continuation byte");
    crate::testport::assert_eq(text_at(text, 5), 65533, "C0 is never a lead");
    crate::testport::assert_eq(text_at(text, 6), 65533, "E0 followed by 80 is overlong: E0 is one replacement");
    crate::testport::assert_eq(text_at(text, 7), 65533, "and the 80 is a stray");
    crate::testport::assert_eq(text_at(text, 8), 65533, "ED A0 is a surrogate: ED is one replacement");
    crate::testport::assert_eq(text_at(text, 9), 65533, "A0 is a stray");
    crate::testport::assert_eq(text_at(text, 10), 65533, "80 is a stray");
    crate::testport::assert_eq(text_at(text, 11), 65533, "F4 90 is past U+10FFFF: F4 is one replacement");
    crate::testport::assert_eq(text_at(text, 12), 65533, "90 is a stray");
    crate::testport::assert_eq(text_at(text, 13), 65533, "80 is a stray");
    crate::testport::assert_eq(text_at(text, 14), 65533, "80 is a stray");
    crate::testport::assert_eq(text_at(text, 15), 65, "decoding resumes");
}
#[test]
fn test_utf8_truncation_and_spans() {
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let n1: i32 = text_append_utf8(text, &crate::testport::hex_blob("41e282")[..], 0, 3);
    let n2: i32 = text_append_utf8(text, &crate::testport::hex_blob("41c3a942")[..], 1, 3);
    let n3: i32 = text_append_utf8(text, &crate::testport::hex_blob("f09f98")[..], 0, 3);
    let n4: i32 = text_append_utf8(text, &crate::testport::hex_blob("f09f9880")[..], 0, 0);
    crate::testport::assert_eq(n1, 2, "A, then a cut-short three-byte sequence is one replacement");
    crate::testport::assert_eq(n2, 1, "the span is [1,3): just the two bytes of e acute");
    crate::testport::assert_eq(n3, 1, "a cut-short four-byte sequence is one replacement");
    crate::testport::assert_eq(n4, 0, "an empty span");
    crate::testport::assert_eq(text_len(text), 4, "four cells in all");
    crate::testport::assert_eq(text_at(text, 0), 65, "A");
    crate::testport::assert_eq(text_at(text, 1), 65533, "replacement");
    crate::testport::assert_eq(text_at(text, 2), 233, "e acute");
    crate::testport::assert_eq(text_at(text, 3), 65533, "replacement");
}
